// Validate bureau_offer fields if bureau_offer exists
if (response.bureau_offer) {
    const bureauOffer = response.bureau_offer;

    // Verify all bureau_offer fields are present
    expect(bureauOffer, 'bureau_offer should have min_loan_amount').to.have.property('min_loan_amount');
    expect(bureauOffer, 'bureau_offer should have max_loan_amount').to.have.property('max_loan_amount');
    expect(bureauOffer, 'bureau_offer should have tenure_list').to.have.property('tenure_list');
    expect(bureauOffer, 'bureau_offer should have roi').to.have.property('roi');
    expect(bureauOffer, 'bureau_offer should have pf_percent').to.have.property('pf_percent');
    expect(bureauOffer, 'bureau_offer should have max_emi').to.have.property('max_emi');
    expect(bureauOffer, 'bureau_offer should have offer_validity').to.have.property('offer_validity');

    // Verify field types and values
    expect(bureauOffer.min_loan_amount).to.be.a('number').and.be.greaterThan(0);
    expect(bureauOffer.max_loan_amount).to.be.a('number').and.be.greaterThan(0);
    expect(bureauOffer.max_loan_amount).to.be.greaterThanOrEqual(bureauOffer.min_loan_amount, 
        'bureau_offer max_loan_amount should be greater than or equal to min_loan_amount');
    expect(bureauOffer.tenure_list).to.be.an('array').and.not.be.empty;
    expect(bureauOffer.tenure_list.every(t => typeof t === 'number' && t > 0)).to.be.true;
    expect(bureauOffer.roi).to.be.a('number').and.be.greaterThan(0);
    expect(bureauOffer.pf_percent).to.be.a('number').and.be.at.least(0);
    expect(bureauOffer.max_emi).to.be.a('number').and.be.greaterThan(0);
    expect(bureauOffer.offer_validity).to.be.a('string').and.not.be.empty;

    // Validate annual_pr if present
    if (bureauOffer.hasOwnProperty('annual_pr')) {
        expect(typeof bureauOffer.annual_pr === 'string' || typeof bureauOffer.annual_pr === 'number').to.be.true;
    }
}

// Validate banking_offer fields if banking_offer exists
