bankingres = await CommonAPI.bankingOffer(app_id);
attachInitResponseToContext(this, bankingres, null);

expect(bankingres.body).to.not.be.empty;
expect(bankingres.body.status).equals('success');
expect(bankingres.body.statusCode).equals(200);
expect(bankingres.body.response.offer_status).equals('Approved');
expect(bankingres.body.response).to.have.property("application_id");
expect(bankingres.body.response).to.have.any.keys('bureau_offer', 'banking_offer');

// Validate bureau_offer fields if bureau_offer exists
if (bankingres.body.response.bureau_offer) {
    const bureauOffer = bankingres.body.response.bureau_offer;

    // Verify all bureau_offer fields are present
    expect(bureauOffer, 'bureau_offer should have min_loan_amount').to.have.property('min_loan_amount');
    expect(bureauOffer, 'bureau_offer should have max_loan_amount').to.have.property('max_loan_amount');
    expect(bureauOffer, 'bureau_offer should have roi').to.have.property('roi');
    expect(bureauOffer, 'bureau_offer should have pf_percent').to.have.property('pf_percent');
    expect(bureauOffer, 'bureau_offer should have max_emi').to.have.property('max_emi');
    expect(bureauOffer, 'bureau_offer should have offer_validity').to.have.property('offer_validity');

    // Verify field types and values
    expect(bureauOffer.min_loan_amount).to.be.a('number').and.be.greaterThan(0);
    expect(bureauOffer.max_loan_amount).to.be.a('number').and.be.greaterThan(0);
    expect(bureauOffer.max_loan_amount).to.be.greaterThanOrEqual(bureauOffer.min_loan_amount, 
        'bureau_offer max_loan_amount should be greater than or equal to min_loan_amount');
    expect(bureauOffer.roi).to.be.a('number').and.be.greaterThan(0);
    expect(bureauOffer.pf_percent).to.be.a('number').and.be.at.least(0);
    expect(bureauOffer.max_emi).to.be.a('number').and.be.greaterThan(0);
    expect(bureauOffer.offer_validity).to.be.a('string').and.not.be.empty;
}

// Validate banking_offer fields if banking_offer exists
if (bankingres.body.response.banking_offer) {
    const bankingOffer = bankingres.body.response.banking_offer;

    // Verify all banking_offer fields are present
    expect(bankingOffer, 'banking_offer should have min_loan_amount').to.have.property('min_loan_amount');
    expect(bankingOffer, 'banking_offer should have max_loan_amount').to.have.property('max_loan_amount');
    expect(bankingOffer, 'banking_offer should have roi').to.have.property('roi');
    expect(bankingOffer, 'banking_offer should have pf_percent').to.have.property('pf_percent');
    expect(bankingOffer, 'banking_offer should have max_emi').to.have.property('max_emi');
    expect(bankingOffer, 'banking_offer should have offer_validity').to.have.property('offer_validity');

    // Verify field types and values
    expect(bankingOffer.min_loan_amount).to.be.a('number').and.be.greaterThan(0);
    expect(bankingOffer.max_loan_amount).to.be.a('number').and.be.greaterThan(0);
    expect(bankingOffer.max_loan_amount).to.be.greaterThanOrEqual(bankingOffer.min_loan_amount, 
        'banking_offer max_loan_amount should be greater than or equal to min_loan_amount');
    expect(bankingOffer.roi).to.be.a('number').and.be.greaterThan(0);
    expect(bankingOffer.pf_percent).to.be.a('number').and.be.at.least(0);
    expect(bankingOffer.max_emi).to.be.a('number').and.be.greaterThan(0);
    expect(bankingOffer.offer_validity).to.be.a('string').and.not.be.empty;

}

const { body } = bankingres;
const { response } = body;
const hasBureauOffer = response.hasOwnProperty('bureau_offer') && response.bureau_offer !== null;
const hasBankingOffer = response.hasOwnProperty('banking_offer') && response.banking_offer !== null;
// If either bureau_offer or banking_offer is present, verify APR and first_emi_date are not present
if (hasBureauOffer || hasBankingOffer) {
    // Check for annual_pr (APR) in bureau_offer
    if (hasBureauOffer) {
        const hasAnnualPR = response.bureau_offer.hasOwnProperty('annual_pr');
        expect(
            !hasAnnualPR,
            `annual_pr (APR) should NOT be present in bureau_offer when bureau_offer object is present. Found: ${response.bureau_offer.annual_pr}`
        ).to.be.true;
    }
    // Check for annual_pr (APR) in banking_offer
    if (hasBankingOffer) {
        const hasAnnualPR = response.banking_offer.hasOwnProperty('annual_pr');
        expect(
            !hasAnnualPR,
            `annual_pr (APR) should NOT be present in banking_offer when banking_offer object is present. Found: ${response.banking_offer.annual_pr}`
        ).to.be.true;
    }
    // Check for first_emi_date at root level
    const hasFirstEmiDate = response.hasOwnProperty('first_emi_date');
    expect(
        !hasFirstEmiDate,
        `first_emi_date should NOT be present at root level when bureau_offer or banking_offer object is present. Found: ${response.first_emi_date}`
    ).to.be.true;
} else {
    // If neither bureau_offer nor banking_offer is present, skip this test
    console.log('  Info: Neither bureau_offer nor banking_offer is present, skipping validation');
    this.skip();
}

