const pollIntervalMs = 5000;
const maxWaitMs = 60000;
const start = Date.now();
let lastRes;
while (true) {
    lastRes = await CommonAPI.pennyStatus(app_id, pennytxnid);
    attachInitResponseToContext(this, lastRes);
