// APR is date-sensitive — disbursal date shifts daily so LOAN_RATE=48 may not always push APR
// above the threshold. If it doesn't, automatically bump LOAN_RATE to 50 and re-update the DB.
const loanAmount    = 100000;
const loanTenure    = 12;
const pfPercent     = 2;
const disbursalDate = new Date().toISOString().slice(0, 10);
const insurancePremiumPayable = await CommonAPI.getMaxInsurancePremium(app_id);
const checkApr = async (loanRate) => {
    const basePf          = CommonAPI.computeBasePf(loanAmount, pfPercent);
    const netDisbursalAmt = CommonAPI.computeNetDisbursal(loanAmount, basePf, insurancePremiumPayable);
    const scheduleBody    = await CommonAPI.getRepaymentSchedule365(
        loanAmount, loanRate, loanTenure, disbursalDate, netDisbursalAmt,
        insurancePremiumPayable, pfPercent
    );
    return scheduleBody?.projectedAPR ?? scheduleBody?.response?.projectedAPR;
};
let loanRate     = 52;
let projectedApr = await checkApr(loanRate);
expect(projectedApr, 'repayment-schedule API must return projectedAPR').to.not.be.null;
if (projectedApr < APR_MAX) {
    // 52% still not enough on this day — bump to 55 and re-write DB + payload
    console.warn(`[HighAPR Setup] projectedAPR=${projectedApr} < APR_MAX=${APR_MAX} with LOAN_RATE=52. Bumping LOAN_RATE to 55.`);
    loanRate = 55;
    await CommonAPI.updateSanctionDetailInDb(app_id, { LOAN_RATE: loanRate });
    CommonAPI.UpdatedPayLoadforofferdetails = {
        ...(CommonAPI.UpdatedPayLoadforofferdetails || {}),
        roi: loanRate,
    };
    projectedApr = await checkApr(loanRate);
    console.log(`[HighAPR Setup] After bump: projectedAPR=${projectedApr} with LOAN_RATE=${loanRate}`);
}
expect(projectedApr, `Projected APR (${projectedApr}) must be >= APR_MAX (${APR_MAX}) to trigger suppression`).to.be.gte(APR_MAX);
console.log(`[HighAPR Setup Verify] projectedAPR=${projectedApr} >= APR_MAX=${APR_MAX} with LOAN_RATE=${loanRate} ✅`);

