const actualBPI = parseFloat(body.response.sanction_details.bpi);
expect(actualBPI).to.equal(0, 'Failed Scenario 4 (Final): BPI must be 0');

const { body } = finalOfferDetailsRes;
if (!body?.response?.sanction_details) { this.skip(); return; }
const sd = body.response.sanction_details;
const actualApr = parseFloat(sd.annual_pr);
expect(actualApr).to.be.greaterThan(0);
const appDb = await CommonAPI.getApplicationDetailsFromDb(app_id);
const is365Day = appDb.body.application.EMI_365_DAY_BASIS;
const loanAmount = parseFloat(sd.loan_amount);
const emi = parseFloat(sd.emi);
const tenure = parseFloat(sd.tenure);
const pfPercent = parseFloat(sd.amount_payable.processingFeePercent);
const basePf  = loanAmount * pfPercent / 100;
const kfsPf   = basePf * (1 + 18 / 100);
const bpiApr  = parseFloat(sd.bpi) || 0;
if (is365Day) {
    // 365-day + compliance ON: basePf (ex-GST); 365-day + compliance OFF: kfsPf (with GST)
    const net365Pf = aprComplianceEnabled ? basePf : kfsPf;
    const netDisbursal = loanAmount - net365Pf - bpiApr;
    const disbursalDate = new Date().toISOString().slice(0, 10);
    const scheduleBody = await CommonAPI.getRepaymentSchedule365(loanAmount, sd.roi, tenure, disbursalDate, netDisbursal);
    const installments = scheduleBody.installments || scheduleBody.response?.installments || [];
    if (installments.length > 0) {
        const expectedApr = CommonAPI.computeAprFromInstallments(netDisbursal, installments);
        expect(Math.abs(actualApr - expectedApr)).to.be.at.most(0.05,
            `[OS-2096] 365-day APR mismatch. Expected: ${expectedApr}, Got: ${actualApr}`);
    }
} else {
    // 360-day APR: compliance ON → basePf (ex-GST), compliance OFF → kfsPf (with GST)
    const pfForApr = aprComplianceEnabled ? basePf : kfsPf;
    const netDisbursal = loanAmount - pfForApr - bpiApr;
    const expectedApr = CommonAPI.computeApr360(netDisbursal, tenure, emi);
    expect(Math.abs(actualApr - expectedApr)).to.be.at.most(0.05,
        `[OS-2096] 360-day APR mismatch. Expected: ${expectedApr}, Got: ${actualApr}`);
}

