// Fetch task first — PL_EMBD_DISBURSAL_006.29 computes and writes ANNUAL_PERCENTAGE_RATE to DB
const result = await CommonAPI.getSelectedTask(app_id, APR_COMPLIANCE_TASK);
taskData = result?.response?.[0];
// Task has run and written ANNUAL_PERCENTAGE_RATE to DB — read it, compute independently, make gate decision
if (aprComplianceEnabled) {
    const appDb = await CommonAPI.getApplicationDetailsFromDb(app_id);
    const sanctionDetail = appDb.body.application?.SANCTION_DETAIL;

    // Independently compute APR using same formula as the task
    const is365Day = appDb.body.application?.EMI_365_DAY_BASIS;
    const { LOAN_AMOUNT, LOAN_RATE, LOAN_TENURE, PROCESSING_FEE } = sanctionDetail;
    const emi = parseFloat(sanctionDetail.EMI);
    const basePfTask = (PROCESSING_FEE / 100) * LOAN_AMOUNT;
    if (!is365Day && emi > 0) {
        const netDisbursal = LOAN_AMOUNT - basePfTask;
        computedRegularApr = CommonAPI.computeApr360(netDisbursal, LOAN_TENURE, emi);
    } else if (is365Day) {
        try {
            const netDisbursal = LOAN_AMOUNT - basePfTask;
            const disbursalDate = new Date().toISOString().slice(0, 10);
            const scheduleBody = await CommonAPI.getRepaymentSchedule365(LOAN_AMOUNT, LOAN_RATE, LOAN_TENURE, disbursalDate, netDisbursal);
            const installments = scheduleBody?.installments || scheduleBody?.response?.installments || [];
            if (installments.length > 0) {
                computedRegularApr = CommonAPI.computeAprFromInstallments(netDisbursal, installments);
            }
        } catch (err) {
            console.warn(`[APR Task] Could not compute 365-day APR: ${err.message}`);
        }
    }
    // Primary: use computed APR. If computed APR < APR_MAX (formula/date rounding), fall back to
    // DB ANNUAL_PERCENTAGE_RATE written by the task itself — it may have used a different date context.
    if (computedRegularApr != null && parseFloat(computedRegularApr) >= APR_MAX) {
        regularAprExceedsMax = true;
    } else if (regularApr != null) {
        regularAprExceedsMax = parseFloat(regularApr) >= APR_MAX;
        if (regularAprExceedsMax) {
            console.warn(`[APR Task] computedRegularApr=${computedRegularApr} < APR_MAX but DB ANNUAL_PERCENTAGE_RATE=${regularApr} >= APR_MAX — using DB value`);
        }
    } else {
        regularAprExceedsMax = false;
         // ANNUAL_PERCENTAGE_RATE written to DB by the task — source of truth for gate decision
    regularApr = sanctionDetail?.ANNUAL_PERCENTAGE_RATE;
    }
    CommonAPI.writeTestContext({ regularAprExceedsMax, regularApr, computedRegularApr });
    console.log(`[APR Task] ANNUAL_PERCENTAGE_RATE(DB)=${regularApr}, computedRegularApr=${computedRegularApr}, APR_MAX=${APR_MAX}, regularAprExceedsMax=${regularAprExceedsMax}`);
} else {
    console.log(`[APR Task] enabled=false — gate inactive.`);
}

